def count_unnecessary_cards(N, K, cards):
    unnecessary_count = 0

    # Check all subsets of cards
    for r in range(1, N + 1):
        for subset in combinations(cards, r):
            if sum(subset) >= K:
                # Check if removing each card in the subset results in a good subset
                for i in range(r):
                    if sum(subset[:i] + subset[i+1:]) < K:
                        break
                else:
                    # If we didn't break, all cards in this subset are unnecessary
                    unnecessary_count += r

    # Since each card is counted multiple times, we need to divide by the number of times each card appears
    # Each card appears in 2^(N-1) subsets (all subsets that include it)
    unnecessary_count = sum(1 for card in cards if sum(cards) - card >= K)

    return unnecessary_count

